SELECT id
FROM reservations
WHERE res_date = #{today}
AND make_status = 'RESERVED'
AND cake_id = #{cakeId}
AND cake_size = #{cakeSize}
ORDER BY res_time ASC
LIMIT 1

SELECT COUNT(*)
FROM reservations
WHERE res_date = #{resDate}

