res_date = #{reservation.resDate}, res_time = #{reservation.resTime}, cake_size = #{reservation.cakeSize}, contact = #{reservation.contact}, paid = #{reservation.paid}, note = #{reservation.note}, updated_at = NOW()
WHERE id = #{id}

